import CubeMark from './CubeMark.astro'
import { content, site } from '../lib/content'
import type { Lang } from '../lib/content'
import { siblingPath } from '../lib/i18n'
import { ui } from '../lib/ui'

interface Props {
  lang: Lang
}

const { lang } = Astro.props
const otherLang: Lang = lang === 'es' ? 'en' : 'es'
const t = content[lang]
const siblingHref = siblingPath(Astro.url.pathname, otherLang)

// The sections these point at arrive with issues 08-13. Until then the links are inert
// by design: the delegated handler of `motion/anchors.ts` no-ops when the target is
// missing. The links only carry `data-nav-link`; the behavior is not owned here.
const sections = [
  { href: '#about', label: t.navAbout },
  { href: '#work', label: t.navWork },
  { href: '#projects', label: t.navProjects },
  { href: '#contact', label: t.navContact },
]
---

<nav class="nav">
  <div class="inner container-page">
    <a class="brand" href="#top" data-nav-link data-brand>
      <CubeMark size={20} />
      <span class="brand-text" data-brand-text>{site.name}</span>
    </a>

    <ul class="sections">
      {
        sections.map(({ href, label }) => (
          <li>
            <a href={href} data-nav-link>
              {label}
            </a>
          </li>
        ))
      }
    </ul>

    {
      /* A real link, so the translation is reachable without JS. Base's inline script owns
      the click that records the choice; this only has to carry `data-lang-toggle`. */
    }
    <a
      class="toggle lang font-mono text-label"
      href={siblingHref}
      rel="alternate"
      hreflang={otherLang}
      data-lang-toggle={otherLang}
    >
      <span class="lang-current">{lang.toUpperCase()}</span> / {otherLang}
    </a>

    <button
      class="toggle theme"
      type="button"
      aria-label={ui[lang].themeToggle}
      aria-pressed="false"
      data-theme-toggle
    >
      <span class="dial" aria-hidden="true"></span>
    </button>
  </div>
</nav>

<style>
  /* Full width for the glass background and the border; `.inner` is the part that
     aligns to the page grid — see `container-page` in `app.css` (spec 19) and spec 20. */
  .nav {
    position: sticky;
    top: 0;
    z-index: 20;
    height: var(--nav-h);
    background: var(--color-glass);
    backdrop-filter: blur(18px) saturate(1.4);
    border-bottom: 1px solid var(--color-line);
  }

  /* A plain block child of `.nav`, not a flex item, so `container-page`'s own
     `max-width` + `margin-inline: auto` center it without restating the width formula
     `Method.astro`'s `.inner` needs (that one is a flex item and cannot inherit
     block layout's `width: auto`). */
  .inner {
    display: flex;
    align-items: center;
    gap: 14px;
    height: 100%;
  }

  .brand {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-right: auto;
    font-weight: 600;
    letter-spacing: -0.01em;
    color: var(--color-ink);
  }

  /* Wide enough for the resolved name, so the scramble never resizes the nav. */
  .brand-text {
    display: inline-block;
    min-width: 9.2em;
    font-variant-numeric: tabular-nums;
  }

  .sections {
    display: flex;
    gap: 22px;
    font-size: 14px;
    color: var(--color-dim);
  }

  .sections a:hover {
    color: var(--color-ink);
  }

  /* No mobile menu is designed: the links go, both toggles stay. */
  @media (width < 720px) {
    .sections {
      display: none;
    }
  }

  /* `flex`, not `grid`: a grid container wraps every stray text run in its own
     anonymous item, and `grid-auto-flow: row` stacked `<span>ES</span>` and the
     trailing " / en" text node onto two lines. Flex's default row direction keeps
     anonymous items on one line (PV3-26). */
  .toggle {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 34px;
    border: 1px solid var(--color-line);
    border-radius: 999px;
    color: var(--color-dim);
    transition: border-color 0.2s;
  }

  .toggle:hover {
    border-color: var(--color-accent);
  }

  .lang {
    padding-inline: 12px;
    white-space: nowrap;
  }

  .lang-current {
    color: var(--color-ink);
  }

  .theme {
    width: 34px;
    background: transparent;
    cursor: pointer;
    color: var(--color-ink);
  }

  /* Half-filled circle: one half `currentColor`, the other only outlined, tilted so it
     reads as a moon and a sun at once. */
  .dial {
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background: linear-gradient(to right, currentColor 50%, transparent 50%);
    box-shadow: inset 0 0 0 1px currentColor;
    transform: rotate(-30deg);
  }
</style>

<script>
  import { scramble } from '../lib/motion/scramble'
  import { toggleTheme } from '../lib/theme'

  const brand = document.querySelector<HTMLElement>('[data-brand]')
  const brandText = document.querySelector<HTMLElement>('[data-brand-text]')
  if (brand && brandText) {
    // Not while the entry owns the brand: `entryDriver.ts` resolves the name as the mark
    // lands on the nav, and a second run would scramble it under the overlay. The flag is
    // read inside the timer, not around it: this script runs before the hero's, so at this
    // point the driver has not written it yet.
    setTimeout(() => {
      if (document.documentElement.dataset.entry !== 'run') scramble(brandText, 1100)
    }, 300)
    setInterval(() => scramble(brandText, 900), 9000)
    brand.addEventListener('mouseenter', () => scramble(brandText, 700))
  }

  const themeToggle = document.querySelector<HTMLButtonElement>('[data-theme-toggle]')
  if (themeToggle) {
    const reflect = (theme: string | undefined) =>
      themeToggle.setAttribute('aria-pressed', String(theme === 'dark'))

    // The inline script in <head> settled the theme before the first paint; read it from
    // there, never from matchMedia, or a stored choice and the button disagree.
    reflect(document.documentElement.dataset.theme)
    themeToggle.addEventListener('click', () => reflect(toggleTheme()))
  }
</script>

